def subtract(a, b):
    # Filter out empty intervals and normalize
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    if not b_intervals:
        return a_intervals

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    result = []

    for a_start, a_end in a_intervals:
        current = a_start

        for b_start, b_end in merged_b:
            # No overlap with this b interval
            if current >= a_end or b_end <= current:
                continue

            # Add the part before the b interval
            if current < b_start:
                result.append([current, min(a_end, b_start)])

            # Move current past the b interval
            current = max(current, b_end)

            if current >= a_end:
                break

        # Add remaining part after all b intervals
        if current < a_end:
            result.append([current, a_end])

    # Merge touching intervals in result
    if not result:
        return []

    merged_result = [result[0]]
    for start, end in result[1:]:
        if start == merged_result[-1][1]:
            merged_result[-1][1] = end
        else:
            merged_result.append([start, end])

    return merged_result

